import sys; sys.path.insert(0, "/tmp/s6")
from h import call, ref, ver, wait_status, case_for, prepare
s, r = call("C1-create", "staff.a", "POST", "central", "/referrals", {"patient_local_id": "MR-102", "reason": "Stage 6: amendment after submission (synthetic)"}, quiet=True)
rid, REF = r["id"], r["reference"]; prepare(rid)
call("C1-approve-v1", "dr.malik", "POST", "central", f"/referrals/{rid}/approve", {"expected_version": ver(rid)}, quiet=True)
call("C1-submit-v1", "staff.a", "POST", "central", f"/referrals/{rid}/submit", {"expected_version": ver(rid)}, quiet=True)
wait_status(rid, {"submitted"})
call("C2-edit-in-flight", "dr.malik", "PATCH", "central", f"/referrals/{rid}", {"expected_version": ver(rid), "reason": "Amended reason after submission (Stage 6)"}, quiet=True)
r = ref(rid); print(f"[C2] after in-flight edit: status={r['status']} amendment_open={r.get('amendment_open')} submitted_v={r.get('submitted_package_version')}")
call("C3-submit-without-new-approval", "staff.a", "POST", "central", f"/referrals/{rid}/submit", {"expected_version": ver(rid)})
_, items = call("C3-items", "dr.malik", "GET", "central", f"/referrals/{rid}/review-items", quiet=True)
s, a2 = call("C3-approve-v2", "dr.malik", "POST", "central", f"/referrals/{rid}/approve", {"expected_version": ver(rid)}, quiet=True)
print(f"[C3] amendment approval -> {s} v{a2.get('package_version') if s == 200 else a2}")
call("C3-submit-v2", "staff.a", "POST", "central", f"/referrals/{rid}/submit", {"expected_version": ver(rid)}, quiet=True)
import time; time.sleep(12)
r = ref(rid); c = case_for(REF)
_, full = call("C4-case", "dr.ortho", "GET", "spec", f"/specialist/cases/{c['id']}", quiet=True)
print(f"[C4] central: status={r['status']} submitted_v={r.get('submitted_package_version')} amendment_open={r.get('amendment_open')}")
print(f"[C4] specialist: latest_version={full['case']['latest_version']} packages={[(p['version'], p['envelope']['reason'][:40], p['envelope'].get('supersedes_version')) for p in full['packages']]}")
_, p1 = call("C4-pkg1", "dr.malik", "GET", "central", f"/referrals/{rid}/packages/1", quiet=True)
print(f"[C4] central v1 kept: reason={p1['envelope']['reason'][:45]!r} superseded={p1['superseded']}")
